import React, { useState } from 'react';
import { ThemeProvider } from './context/ThemeContext';
import Header from './components/Header';
import ChatWindow from './components/ChatWindow';
import InputBar from './components/InputBar';
import './App.css';
import './themes.css';

function App() {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [detectActive, setDetectActive] = useState(false);

  const handleToggleDetect = () => {
    setDetectActive((prev) => !prev);
  };

  const sendMessage = async () => {
    if (!input.trim()) return;

    const userMessage = { sender: 'user', text: input };
    setMessages((prev) => [...prev, userMessage]);
    setInput('');
    setLoading(true);

    try {
      let responseText = '';

      if (detectActive) {
        // Call adversarial detection API
        const res = await fetch('http://localhost:5000/api/detect', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ text: input }),
        });
        const data = await res.json();
        responseText = `🧪 Detection Result: ${data.result || 'Unknown'}`;
      } else {
        // Normal chat response
        const res = await fetch('http://localhost:5000/api/chat', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ prompt: input }),
        });
        const data = await res.json();
        responseText = data.response;
      }

      const botMessage = { sender: 'bot', text: responseText };
      setMessages((prev) => [...prev, botMessage]);
    } catch {
      setMessages((prev) => [
        ...prev,
        { sender: 'bot', text: '⚠️ Request failed.' },
      ]);
    }

    setLoading(false);
  };

  return (
    <ThemeProvider>
      <div className="app">
        <Header />
        <ChatWindow messages={messages} loading={loading} />
        <InputBar
          input={input}
          setInput={setInput}
          onSend={sendMessage}
          onToggleDetect={handleToggleDetect}
          detectActive={detectActive}
        />
      </div>
    </ThemeProvider>
  );
}

export default App;
